package com.bakeflow.identity;
import static com.bakeflow.identity.IdentityDtos.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;import com.bakeflow.BakeFlowBackendApplication;import com.bakeflow.integration.application.CacheService;import java.util.Set;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.context.ActiveProfiles;import org.springframework.test.context.bean.override.mockito.MockitoBean;import org.springframework.transaction.annotation.Transactional;
@SpringBootTest(classes=BakeFlowBackendApplication.class)@ActiveProfiles("test")@Transactional class IdentityServiceTests{@Autowired IdentityService service;@MockitoBean CacheService cache;@BeforeEach void rate(){when(cache.incrementWithinLimit(anyString(),anyInt(),any())).thenReturn(true);}@Test void hashesPasswordsAndRotatesRefreshTokens(){service.ensureAdmin("Admin@BakeFlow.local","long demo password");var login=service.login(new LoginInput("admin@bakeflow.local","long demo password"),"test","agent");assertThat(login.response().accessToken()).isNotBlank();assertThat(login.refreshToken()).hasSizeGreaterThan(32);var rotated=service.refresh(login.refreshToken(),"agent");assertThat(rotated.refreshToken()).isNotEqualTo(login.refreshToken());assertThatThrownBy(()->service.refresh(login.refreshToken(),"agent")).isInstanceOf(IdentityException.class).extracting("code").isEqualTo("REFRESH_TOKEN_REUSED");}@Test void rejectsWrongPasswordAndPolicy(){service.ensureAdmin("admin2@bakeflow.local","long demo password");assertThatThrownBy(()->service.login(new LoginInput("admin2@bakeflow.local","wrong password"),"other","agent")).isInstanceOf(IdentityException.class);assertThatThrownBy(()->service.create(new UserInput("User","u@bakeflow.local","short",Set.of("VIEWER"),true))).isInstanceOf(IdentityException.class);}@Test void createsViewerWithoutUserPermission(){var user=service.create(new UserInput("Viewer","viewer@bakeflow.local","a valid passphrase",Set.of("VIEWER"),true));assertThat(user.permissions()).contains("ITEM_READ").doesNotContain("USER_READ","USER_WRITE");}}
